<script setup lang="ts">
import{computed,onMounted,ref}from'vue';import{obtenerAvance,obtenerRecorrido,urlAtipicos,urlPadron,type Dashboard,type Distrito,type Lecturista,type Punto}from'../services/avanceLecturas'
const data=ref<Dashboard>({distritos:[],tipos:[],alertas:[],lecturistas:[],recientes:[],resumen:{validas:0,observadas:0,atipicas:0,altos_consumidores:0,criticas:0}}),selected=ref(''),loading=ref(false),error=ref(''),trackUser=ref<Lecturista|null>(null),trackDate=ref(new Date().toISOString().slice(0,10)),points=ref<Punto[]>([]),loadingTrack=ref(false);const pct=(x:Distrito)=>x.total?Math.round(x.registradas*100/x.total):0;const progress=computed(()=>data.value.distrito?pct(data.value.distrito):0);const maxUser=computed(()=>Math.max(1,...data.value.lecturistas.map(x=>x.lecturas)));const maxMetric=(values:{total:number}[])=>Math.max(1,...values.map(x=>x.total))
async function load(id:string|number=selected.value){loading.value=true;error.value='';selected.value=String(id);try{data.value=await obtenerAvance(id)}catch(e){error.value=msg(e)}finally{loading.value=false}}async function showTrack(x:Lecturista){if(!data.value.distrito)return;trackUser.value=x;loadingTrack.value=true;error.value='';try{points.value=(await obtenerRecorrido(data.value.distrito.id,x.id,trackDate.value)).puntos}catch(e){error.value=msg(e)}finally{loadingTrack.value=false}}function msg(e:unknown){return e instanceof Error?e.message:'No se pudo cargar el avance.'}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / Medición / Avance de lecturas</nav><header class="hero"><div class="mark">AV</div><div><small>EVAN · MONITOREO DE CAMPO</small><h1>Avance de lecturas</h1><p>Progreso, calidad y productividad del proceso de toma de lecturas.</p></div><label>Distrito<select v-model="selected" @change="load()"><option value="">Resumen general</option><option v-for="x in data.distritos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label></header><p v-if="error" class="flash bad">{{error}}</p><section class="districts"><button v-for="x in data.distritos" :key="x.id" :class="{active:selected==String(x.id)}" @click="load(x.id)"><span>{{x.nombre}}</span><b>{{x.registradas}} / {{x.total}}</b><i><em :style="{width:pct(x)+'%'}"></em></i><small>{{pct(x)}}%</small></button></section><div v-if="loading" class="empty">Cargando indicadores…</div><template v-else-if="data.distrito"><section class="progress"><div><small>AVANCE DEL DISTRITO</small><h2>{{data.distrito.nombre}}</h2><strong>{{data.distrito.registradas}} <span>/ {{data.distrito.total}} lecturas</span></strong></div><div class="ring" :style="{'--p':progress*3.6+'deg'}"><b>{{progress}}%</b></div><footer><a :href="urlPadron(data.distrito.id)" target="_blank">Imprimir padrón</a><a :href="urlAtipicos(data.distrito.id)" target="_blank">Reporte de atípicos</a></footer></section><section class="kpis"><article><span>Lecturas válidas</span><b>{{data.resumen.validas}}</b></article><article><span>Observadas</span><b>{{data.resumen.observadas}}</b></article><article><span>Atípicas</span><b>{{data.resumen.atipicas}}</b></article><article><span>Altos consumidores</span><b>{{data.resumen.altos_consumidores}}</b></article><article><span>En crítica</span><b>{{data.resumen.criticas}}</b></article></section><section class="grid"><article class="panel"><header><small>CALIDAD</small><h2>Tipos de lectura</h2></header><div class="bars"><div v-for="x in data.tipos" :key="x.nombre"><label><span>{{x.nombre}}</span><b>{{x.total}}</b></label><i><em :style="{width:x.total*100/maxMetric(data.tipos)+'%'}"></em></i></div></div></article><article class="panel warning"><header><small>CONTROL</small><h2>Alertas de lectura</h2></header><div class="bars"><div v-for="x in data.alertas" :key="x.nombre"><label><span>{{x.nombre}}</span><b>{{x.total}}</b></label><i><em :style="{width:x.total*100/maxMetric(data.alertas)+'%'}"></em></i></div></div></article><article class="panel"><header><small>PRODUCTIVIDAD</small><h2>Lecturas por usuario</h2></header><div class="users"><button v-for="x in data.lecturistas" :key="x.id" @click="showTrack(x)"><span>{{x.usuario}}</span><i><em :style="{width:x.lecturas*100/maxUser+'%'}"></em></i><b>{{x.lecturas}}</b></button></div></article><article class="panel"><header><small>ACTIVIDAD</small><h2>Últimos registros</h2></header><div class="recent"><button v-for="x in data.recientes" :key="x.id" @click="$router.push({name:'comercial-medicion-lecturas',query:{lectura:x.id}})"><time>{{x.fecha}}</time><span>{{x.usuario}} · Medidor {{x.medidor}}</span><small>{{x.direccion}}</small></button></div></article></section></template><div v-else-if="!loading" class="empty">Seleccione un distrito para ver el tablero detallado.</div>
<div v-if="trackUser&&data.distrito" class="backdrop" @mousedown.self="trackUser=null"><section class="modal"><header><div><small>RECORRIDO DE LECTURAS</small><h2>{{trackUser.usuario}} · {{data.distrito.nombre}}</h2></div><button @click="trackUser=null">×</button></header><label>Fecha<input v-model="trackDate" type="date" @change="showTrack(trackUser)"></label><div v-if="loadingTrack" class="empty">Cargando ubicaciones…</div><div v-else-if="!points.length" class="empty">No existen puntos registrados para esta fecha.</div><div v-else class="track"><article v-for="(x,i) in points" :key="x.id"><b>{{i+1}}</b><div><strong>{{x.fecha}} · Medidor {{x.medidor}}</strong><span>{{x.direccion}}</span><small>{{x.latitud}}, {{x.longitud}}</small></div></article></div><footer><span>{{points.length}} puntos encontrados</span><button @click="trackUser=null">Cerrar</button></footer></section></div></div></template>
